#!/usr/bin/env python3
r"""C496 independent replay.

Re-derives the load-bearing C496 facts with independent code and asserts agreement with the
committed certificate notes/2026-07-23-c496-bihecke-two-sort-coupling.json:

  * PGL_2(11) is regenerated by generator closure (not the primary checker's exhaustive tuple
    enumeration); order 1320 is confirmed.
  * the symmetric-square (conic) cell action, the intrinsic edge coordinate u = XZ/Y^2, the
    determinant square test, and the Legendre symbol are reimplemented from scratch here.
  * for each of the four pointed states the 22 opponent moves are recovered, the frame-fixed
    square kernel C5 is rebuilt, the six C5-orbits are recomputed by union-find, and the
    additive-incidence profile of every orbit (candidate reply-cell sets) is recomputed.
  * the OBSTRUCTION is re-verified: the two live orbits (u=8, u=9) have identical incidence
    profiles yet opposite committed value (P, N); 2 incidence classes vs 3 value classes.
  * the COUPLING is re-verified: Legendre(8) = -1, Legendre(9) = +1 (so value = [chi(u) = -1]
    on the live fibre), the balanced live Gauss sum 5*chi(8) + 5*chi(9) = 0, and the nonsquare
    coset preserves u pointwise.

Trust boundary: the residual-grid game engine (notes/2026-07-08-intrusion-census.py) and the
frozen C447/C460 geometric constructors are the shared frozen inputs -- the game *value* recursion
is not independently re-implemented here (it is the shared engine, exactly as the primary checker
and the C80/C495 bundles use it). This replay independently re-derives the group, the action, u,
Legendre, the orbit decomposition, the incidence-profile identity, and the character coupling, and
asserts equality with the committed certificate's recorded values.

Run from /home/tavis/src/othello:
    python3 rust/scripts/c496_bihecke_two_sort_coupling_replay.py
"""
from __future__ import annotations

import importlib.util
import json
import sys
from pathlib import Path

Q = 11
ROOT = Path(__file__).resolve().parents[2]
CLOUD_PACKET_SOURCE = ROOT / "rust/scripts/c80_c447_cloud_packet.py"
C447_JSON = ROOT / "notes/2026-07-21-c447-cap-knife-edge.json"
CERT = ROOT / "notes/2026-07-23-c496-bihecke-two-sort-coupling.json"


def inv(a):
    return pow(a % Q, -1, Q)


# --- independent PGL_2(11) by generator closure -------------------------------------------------
def mat_mul(m, n):
    (a, b, c, d), (e, f, g, h) = m, n
    return ((a * e + b * g) % Q, (a * f + b * h) % Q, (c * e + d * g) % Q, (c * f + d * h) % Q)


def normalize_mat(m):
    pivot = next(x for x in m if x % Q)
    s = inv(pivot)
    return tuple(x * s % Q for x in m)


def pgl_closure():
    # S: z -> z+1 = (1,1,0,1); T: z -> -1/z = (0,-1,1,0) generate PSL_2(q); adjoin a
    # nonsquare-determinant diagonal D = diag(1, n), n a nonsquare, to reach all of PGL_2(q).
    n = next(x for x in range(2, Q) if pow(x, (Q - 1) // 2, Q) != 1)  # 2 is nonsquare mod 11
    gens = [
        normalize_mat((1, 1, 0, 1)),
        normalize_mat((0, -1 % Q, 1, 0)),
        normalize_mat((1, 0, 0, n)),
    ]
    seen = {normalize_mat((1, 0, 0, 1))}
    frontier = list(seen)
    while frontier:
        nxt = []
        for m in frontier:
            for gcol in gens:
                p = normalize_mat(mat_mul(m, gcol))
                if p not in seen:
                    seen.add(p)
                    nxt.append(p)
        frontier = nxt
    assert len(seen) == Q * (Q * Q - 1), len(seen)  # 1320
    return seen


def mobius_act(m, x):
    a, b, c, d = m
    if x == "inf":
        return "inf" if c == 0 else a * inv(c) % Q
    den = (c * x + d) % Q
    return "inf" if den == 0 else (a * x + b) * inv(den) % Q


def det_is_square(m):
    a, b, c, d = m
    return pow((a * d - b * c) % Q, (Q - 1) // 2, Q) == 1


def legendre(u):
    if u == "inf":
        return "inf"
    if u % Q == 0:
        return 0
    return 1 if pow(u, (Q - 1) // 2, Q) == 1 else -1


def load_cloud_packet_module():
    spec = importlib.util.spec_from_file_location("c496r_cp", CLOUD_PACKET_SOURCE)
    module = importlib.util.module_from_spec(spec)
    sys.modules["c496r_cp"] = module
    spec.loader.exec_module(module)
    return module


def union_find_orbits(points, act_gens):
    parent = {p: p for p in points}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        parent[find(x)] = find(y)

    for p in points:
        for g in act_gens:
            q = g(p)
            if q in parent:
                union(p, q)
    groups = {}
    for p in points:
        groups.setdefault(find(p), set()).add(p)
    return list(groups.values())


def replay_state(cp, game, group, record, endpoint, cert_state):
    repair = record["canonical_shared_edge_cross_sheet_pair"]
    intersection = cp.cloud(repair["plus_matching"]) & cp.cloud(repair["minus_matching"])
    matrix = record["standard_to_cap_projectivity"]
    packet = sorted({cp.cap_cell(matrix, point) for point in intersection})

    # independent frame stabilizer / square kernel using the closure-generated group
    frame = set(record["frame_parameters"])
    frame_stab = [g for g in group if {mobius_act(g, x) for x in frame} == frame]
    square_kernel = [g for g in frame_stab if det_is_square(g)]
    nonsquare_coset = [g for g in frame_stab if not det_is_square(g)]
    assert len(square_kernel) == 5 and len(nonsquare_coset) == 5

    witness = cp.cap_cell(matrix, cp.standard_point(endpoint))
    seed = [tuple(cell) for cell in record["S3"]] + [witness]
    mask = sum(game.bit_for_cell(cell) for cell in seed)

    vinfo = {}
    for _bit, oi in game.iter_bits(game.legal_mask(mask)):
        opponent = game.cell_tuple(oi)
        after = mask | (1 << oi)
        legal = game.legal_mask(after)
        candidates = frozenset(
            i for i, cell in enumerate(packet) if legal & game.bit_for_cell(cell)
        )
        winning = frozenset(
            i for i in candidates if not game.value(after | game.bit_for_cell(packet[i]))
        )
        u = cp.edge_quotient_u(record, repair["shared_p_edge"], opponent)
        vinfo[opponent] = (u, candidates, winning)
    assert len(vinfo) == 22

    # independent orbit decomposition by union-find under the square kernel action
    act_gens = [lambda p, g=g: cp.cap_cell_action(record, g, p) for g in square_kernel]
    orbits = union_find_orbits(set(vinfo), act_gens)
    assert sorted(len(o) for o in orbits) == [1, 1, 5, 5, 5, 5]

    # per-orbit recomputation
    live_profiles = {}
    values = {}
    supports = set()
    for orb in orbits:
        us = {vinfo[c][0] for c in orb}
        assert len(us) == 1
        u = us.pop()
        vertex = next(iter(orb))
        cand, win = vinfo[vertex][1], vinfo[vertex][2]
        value = "P" if win else ("N" if cand else "killed")
        support = tuple(sorted(frozenset().union(*[vinfo[c][1] for c in orb]) or frozenset()))
        supports.add(support)
        if u in (8, 9):
            live_profiles[u] = sorted(sorted(vinfo[c][1]) for c in orb)
            values[u] = value

    # OBSTRUCTION: identical incidence on the value-splitting live fibre
    assert set(live_profiles) == {8, 9}
    assert live_profiles[8] == live_profiles[9]
    assert values[8] == "P" and values[9] == "N"
    assert len(supports) == 2  # killed(empty) + live(pentagon)

    # COUPLING: quadratic character separates the collapsed fibre; balanced Gauss sum; C2 fixes u
    assert legendre(8) == -1 and legendre(9) == 1
    gauss = 5 * legendre(8) + 5 * legendre(9)
    assert gauss == 0
    c2_fixes_u = all(
        cp.edge_quotient_u(record, repair["shared_p_edge"], cp.cap_cell_action(record, g, opp))
        == vinfo[opp][0]
        for g in nonsquare_coset
        for opp in vinfo
    )
    assert c2_fixes_u

    # agreement with the committed certificate for this pointed state
    obs = cert_state["obstruction"]
    cpl = cert_state["coupling"]
    assert obs["additive_incidence_profiles_identical_on_live"] is True
    assert obs["additive_incidence_set_classes"] == len(supports)
    assert obs["value_set_classes"] == 3
    assert [list(p) for p in live_profiles[8]] == obs["shared_candidate_pair_multiset"]
    assert obs["live_orbit_values"] == {"8": "P", "9": "N"}
    assert cpl["value_equals_legendre_u_on_live_fibre"] is True
    assert cpl["balanced_live_gauss_sum"] == gauss
    assert cpl["nonsquare_c2_preserves_u_pointwise"] is True

    # independently re-verify the move-level product formula and the knife-edge straddle
    move_holds = 0
    for opp, (u, cand, win) in vinfo.items():
        is_live = len(cand) > 0
        chi = legendre(u)
        predicted = "P" if (is_live and chi == -1) else ("N" if (is_live and chi == 1) else "killed")
        observed = "P" if win else ("N" if cand else "killed")
        assert predicted == observed
        move_holds += 1
    assert move_holds == 22
    assert cpl["move_level_product_formula_holds_on_all_22"] is True
    assert {legendre(8), legendre(9)} == {-1, 1}
    assert cpl["knife_edge_straddle_live_u_is_square_nonsquare_pair"] is True


def main():
    cert = json.loads(CERT.read_text())
    assert cert["schema"] == "c496-bihecke-two-sort-coupling-v1"
    assert cert["field_order"] == Q

    group = pgl_closure()
    cp = load_cloud_packet_module()
    game = cp.load_game_module().PrimeGridGame(Q)
    source = json.loads(C447_JSON.read_text())

    cert_by_key = {
        (s["class"], str(s["endpoint_parameter"])): s for s in cert["pointed_states"]
    }
    checked = 0
    for record in source["knife_edge_classes"]:
        repair = record["canonical_shared_edge_cross_sheet_pair"]
        for endpoint in repair["shared_p_edge"]:
            key = (record["class"], str(endpoint))
            replay_state(cp, game, group, record, endpoint, cert_by_key[key])
            checked += 1
    assert checked == len(cert["pointed_states"]) == 4
    assert cert["verdict"] == (
        "BI_HECKE_BIMODULE_IS_VALUE_BLIND_OBSTRUCTION; "
        "COUPLING_IS_ADDITIVE_TIMES_MULTIPLICATIVE_GAUSS_PAIRING_NOT_A_SINGLE_BIMODULE"
    )
    print(f"C496 independent replay: PASS ({checked} pointed states, PGL_2(11) closure order 1320)")


if __name__ == "__main__":
    main()
